def withdraw(balance, amount):
    if amount > balance:
        raise ValueError("잔액 부족")
    return balance - amount

try:
    b = withdraw(100, 30)
    b = withdraw(b, 100)
    print(b)
except ValueError as e:
    print("오류:", e)
